/**
 * Domain types for the UI, derived from the backend's OpenAPI contract.
 * `openapi.gen.ts` is generated by `npm run gen:api` from the running backend; never edit it
 * by hand. If the backend schema changes, regenerating makes TypeScript flag every caller.
 */
import type { components } from "./openapi.gen";

type Schemas = components["schemas"];

export type Account = Schemas["AccountRead"];
export type AccountCreate = Schemas["AccountCreate"];
export type AccountFund = Schemas["AccountFund"];
export type AccountBalance = Schemas["AccountBalance"];
export type AccountKind = Schemas["AccountKind"];
export type Transfer = Schemas["TransferRead"];
export type TransferCreate = Schemas["TransferCreate"];
export type TransferKind = Schemas["TransferKind"];
export type TransferStatus = Schemas["TransferStatus"];
export type LedgerEntry = Schemas["LedgerEntryRead"];
export type LedgerEntryRole = Schemas["LedgerEntryRole"];
export type Reconciliation = Schemas["ReconciliationRead"];
export type BalanceMismatch = Schemas["BalanceMismatchRead"];
export type SystemSummary = Schemas["SystemSummaryRead"];
export type DailyTransferActivity = Schemas["DailyTransferActivity"];
export type TransferKindSummary = Schemas["TransferKindSummary"];
export type ErrorBody = Schemas["ErrorBody"];
export type ErrorResponse = Schemas["ErrorResponse"];

export interface Page<T> {
  items: T[];
  limit: number;
  offset: number;
}

/** /health/ready is outside /api/v1 and returns an untyped JSONResponse. */
export interface ReadinessReport {
  status: "ok" | "degraded";
  replica?: string;
  database?: "ok" | "unavailable";
  redis?: "ok" | "unavailable" | "not_used";
}

export const TRANSFER_KINDS: readonly TransferKind[] = ["transfer", "dev_funding", "legacy_opening_balance"];

export const TRANSFER_KIND_LABELS: Record<TransferKind, string> = {
  transfer: "Transfer",
  dev_funding: "Simulated funding",
  legacy_opening_balance: "Legacy opening balance",
};
